func _process(delta: float):
 if surface!=null:
  var viewport=get_viewport().get_visible_rect().size;var scale_factor=minf(viewport.x/1504.,viewport.y/860.);surface.scale=Vector2.ONE*scale_factor;surface.position=Vector2.ZERO;surface.size=viewport/scale_factor
  if menu_panels!=null:menu_panels.arrange(surface.size)
 if battle==null:return
 if not ready_started:
  var director=runtime.get_node("TacticalBattleView").battle_presentation
  if director.stage=="ready" and director.ready_clock>.7:
   var begin=Fixture.begin_review(runtime, battle);ready_started=begin!=null and begin.success
   if ready_started:
    for force_id in battle.get_sorted_tactical_force_ids():
     if battle.get_tactical_force(force_id).side_id==battle.attacker_side_id:preload("res://battle/core/battle_force_command_service.gd").set_command(battle,force_id,"push")
  return
 if custom_battle and runtime.get_node("TacticalBattleView").battle_presentation.results_acknowledged:
  return_to_setup();return
 if battle.battle_phase=="active":
  battle_clock+=delta
  Runtime.advance(battle,minf(delta,.1))
func _input(event: InputEvent):
 if event is InputEventKey and event.pressed and event.keycode==KEY_ESCAPE and runtime!=null:
  var orders=runtime.tactical_orders_controller
  if orders!=null and (not orders.selected_participant_ids.is_empty() or not orders.pending_command_id.is_empty()):
   orders.handle_input(runtime.get_node("TacticalBattleView"),event)
  else:return_to_setup()
  get_viewport().set_input_as_handled()

